    }

    function fn_callBarcodeInfo(params) {

        // 컨트롤 / 액션
        var controllerName = $(""#controllerName"").val();
        var actionName = $(""#actionName"").val();

        var callUrl = ""/"" + controllerName + ""/"" + actionName;
        var request = JSON.stringify(params);


        // 화면 초기화
        $(""#item_cd"").val("""");
        $(""#item_nm"").val("""");
        $(""#test_no"").val("""");
        $(""#keeping_unit"").val("""");
        $(""#receipt_pack_qty"").val("""");
        $(""#receipt_pack_remain_qty"").val("""");
        $('#productList > tbody').empty();
        //$(""ul.pagination"").children().remove();

        $.ajax({
            method: ""POST"",
            data: request,
            url: callUrl,
            dataType: 'json',
            contentType: 'application/json; charset=UTF-8',
            success: function (data) {
                console.log(data);

                $(""#list_count"").val(data.length);
                $(""#current_page"").val(1);

               ");
