                        type: 'error'
                        //timer: 1000
                    });


                    return;

                } else {

                    $(""#item_cd"").val(data.item_cd);
                    $(""#item_nm"").val(data.item_nm);
                    $(""#test_no"").val(data.test_no);
                    $(""#keeping_unit"").val(data.keeping_unit);
                    $(""#receipt_pack_qty"").val(data.receipt_pack_qty);
                    $(""#receipt_pack_remain_qty"").val(data.receipt_pack_remain_qty);
                    $(""#barcode"").val(data.barcode);

