                fn_loading('show');
            }, complete: function () {
                fn_loading('hide');
            }, error: function (data) {
                alert('error' + data.status);
            }
        });



    }

    /*
     * 완제품 수불현황 히스토리
     */
    function fn_GridSelect(params, controllerName, actionName) {

        var callUrl = ""/"" + controllerName + ""/"" + actionName;

        var request = JSON.stringify(params);

        $.ajax({
            method: ""POST"",
            data: request,
            url: callUrl,
            dataType: 'json',
            contentType: 'application/json; charset=UTF-8',
            success: function (data) {

                $('#productList > tbody').empty();
                $(""#list_count"").val(data.length);
                $(""#current_page"").val(1);

                for (var i = 0; i < data.l");
            WriteLiteral(@"ength; i++) {

                    var receipt_date = data[i].receipt_date;
                    var receipt_type_nm = data[i].receipt_type_nm;
                    var receipt_qty = data[i].receipt_qty;

                    $('#productList > tbody').append('<tr class=""row100 body"" style=""text-align: center;"" ><td class=""cell100 column1"">' + receipt_date
                        + '</td><td class=""cell100 column2"">' + receipt_type_nm
                        + '</td><td class=""cell100 column3"">' + receipt_qty + '</td></tr>');
                }
                // 테이블 resize
                resize_table();

                // 페이징 처리
                pagination();

                if ($(""#first_page"").val() === '1') {
                    pagination();
                    $(""#first_page"").val('2');
                }

                console.log(data);
            },
            error: function (data) {
                alert('error' + data.status);
            }
        });
    }


    fun");
            WriteLiteral(@"ction resize_table() {
        var count = $(""#productList tbody tr"").length;
        var newHeight = 48 + (count * 45);

        $(""#productList"").parent().removeClass(""h-50"");
        $(""#productList"").parent().height(newHeight);
    }


</script>");
